    ta: "வணக்கம்! அருகில் உள்ள ஒருவருக்காக {item} வாங்குகிறேன். உங்கள் விலை என்ன?",
    ne: "नमस्ते! म नजिकैको एक जनाका लागि {item} किन्दैछु। तपाईंको मूल्य कति?",
