  "Your stall is saved to your Molbhav account. Buyers’ agents see its name and prices, never your lowest.":
    {
      hi: "आपकी दुकान आपके मोलभाव खाते में सेव है। खरीदारों के एजेंट उसका नाम और दाम देखते हैं, आपका सबसे कम दाम कभी नहीं।",
      mr: "तुमचं दुकान तुमच्या मोलभाव खात्यात जतन आहे. ग्राहकांचे एजंट नाव आणि किंमती पाहतात, तुमची किमान किंमत कधीच नाही.",
      ta: "உங்க கடை உங்க Molbhav கணக்கில் சேமிக்கப்பட்டிருக்கு. வாங்குபவர்களின் ஏஜென்ட்கள் பெயரையும் விலைகளையும் பார்ப்பாங்க, உங்க குறைந்த விலையை ஒருபோதும் இல்லை.",
      ne: "तपाईंको पसल Molbhav खातामा सुरक्षित छ। ग्राहकका एजेन्टले यसको नाम र मूल्य देख्छन्, तपाईंको न्यूनतम मूल्य कहिल्यै देख्दैनन्।",
      ja: "お店はMolbhavのアカウントに保存されています。お客さんのエージェントに見えるのは店名と価格だけで、最低価格は見えません。",
      ko: "가게는 Molbhav 계정에 저장돼요. 손님의 에이전트는 이름과 가격만 보고, 최저 가격은 절대 보지 못해요.",
      zh: "你的摊位已保存到 Molbhav 账户。买家的代理能看到名称和价格，永远看不到你的最低价。",
      es: "Tu puesto está guardado en tu cuenta de Molbhav. Los agentes de los compradores ven su nombre y precios, nunca tu mínimo.",
      fr: "Votre stand est enregistré dans votre compte Molbhav. Les agents des acheteurs voient son nom et ses prix, jamais votre minimum.",
    },
