  "Easiest: join the sign’s hotspot, save market Wi‑Fi only, then enter the 6-digit code from its screen here.":
    {
      hi: "सबसे आसान: साइन का हॉटस्पॉट जोड़ें, सिर्फ़ बाज़ार Wi‑Fi सेव करें, फिर स्क्रीन का ६‑अंकों का कोड यहाँ डालें।",
      mr: "सगळ्यात सोपं: साइनचा हॉटस्पॉट जोडा, फक्त बाजार Wi‑Fi सेव्ह करा, मग स्क्रीनचा ६‑अंकी कोड इथे टाका.",
      ta: "எளிது: சைன் ஹாட்ஸ்பாட்டைச் சேருங்க, சந்தை Wi‑Fi மட்டும் சேமிங்க, பிறகு திரையில் உள்ள 6 இலக்கக் குறியீட்டை இங்கே உள்ளிடுங்க.",
      ne: "सबैभन्दा सजिलो: साइनको हटस्पट जोड्नुहोस्, बजार Wi‑Fi मात्र सेभ गर्नुहोस्, अनि स्क्रिनको ६‑अङ्कको कोड यहाँ हाल्नुहोस्।",
      ja: "いちばん簡単：看板のホットスポットに入り、市場Wi‑Fiだけ保存し、画面の6桁コードをここに入力。",
      ko: "가장 쉬운 방법: 간판 핫스팟에 접속하고 시장 Wi‑Fi만 저장한 뒤, 화면의 6자리 코드를 여기에 입력하세요.",
      zh: "最简单：连上招牌热点，只保存市场 Wi‑Fi，再把屏幕上的六位数代码填到这里。",
      es: "Lo más fácil: únete al hotspot del letrero, guarda solo el Wi‑Fi del mercado y escribe aquí el código de 6 dígitos de su pantalla.",
      fr: "Le plus simple : rejoignez le hotspot de l’enseigne, enregistrez uniquement le Wi‑Fi du marché, puis saisissez ici le code à 6 chiffres de l’écran.",
    },
